  function K(name){ SKILL = { name: name, lessons: [] }; CAT.skills.push(SKILL); }
  function X(title, pairs){
    var p = pairs.split('|'), words = [];
    for (var i = 0; i + 1 < p.length; i += 2) words.push({ es: p[i], en: p[i + 1] });
    N++;
    SKILL.lessons.push({ id: CAT.id + N, title: title, words: words });
  }

